module top_module (
    input wire clk,
    input wire reset,
    input wire [1023:0] in,
    input wire [2:0] sel,
    input wire [2:0] vec,
    output wire [3:0] out,
    output wire o2,
    output wire o1,
    output wire o0 );

    wire [3:0] mux_out;
    wire [3:0] shifter_out;

    // 256-to-1 Multiplexer
    mux_256to1 mux_inst (
        .in(in),
        .sel(sel),
        .out(mux_out)
    );

    // Barrel Shifter
    barrel_shifter bs_inst (
        .in(mux_out),
        .vec(vec),
        .out(shifter_out),
        .o0(o0),
        .o1(o1),
        .o2(o2)
    );

    // Functional Module
    function_module func_inst (
        .mux_out(mux_out),
        .shifter_out(shifter_out),
        .vec(vec),
        .out(out)
    );

