                        (op == 3'b011) ? (A | shifted_value) :
                        (op == 3'b100) ? (A ^ shifted_value) :
                        (op == 3'b101) ? (shifted_value << 1) :
                        4'b0;

    // Output
    assign S = alu_result;

endmodule
```

