    input [3:0] A,
    input [1:0] S,
    input D,
    output reg [3:0] B
);

    reg [3:0] shift_reg;

    always @(*) begin
        case(S)
            2'b00: shift_reg = A;
            2'b01: shift_reg = {A[2:0], A[3]};
