module binary_to_gray_4bit (
    input [3:0] B,
    output reg [3:0] G
);
always @(*) begin
    G[3] = B[3];
    G[2] = B[3] ^ B[2];
    G[1] = B[2] ^ B[1];
    G[0] = B[1] ^ B[0];
end
endmodule

module functional_module (
    input [3:0] counter_out,
    input [3:0] gray_out,
    output reg [3:0] final_output
);
always @(*) begin
    final_output = counter_out ^ gray_out;
end
endmodule
