    input a,
    input b,
    input select,
    input clk,
    output reg out_always_ff
);

wire xor_out;
wire or_out;
wire not_select;

assign not_select = ~select;
assign xor_out = (a & ~b) | (~a & b);
assign or_out = a | b;

